/**
 * @method
 * @name scwin.fnInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnInit = async function () {
    /* sdd-asis-lifecycle:begin fnInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod(' + "1" + ')');
    await scwin.fnOrder("1", "D");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnOrder
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode stat
 * @returns
 * @hidden N
*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!chkPeriod_year(fromDate, toDate, 3)) {
        return;
    }
    const chkDt = fromDate.replace(/\-/g, '');
    if (parseInt(chkDt) < 19990101) {
        await $c.win.alert("조회는 1999년 1월 1일 이후부터 가능합니다.");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "pubprcCmpStkprcByIssueSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "pubprcCmpStkprcByIssue_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "pubprcCmpStkprcByIssueSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "pubprcCmpStkprcByIssue_down");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnChkLmtDate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnChkLmtDate = async function () {
    /* sdd-asis-lifecycle:begin fnChkLmtDate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const dateVal = $c.util.getComponent('cal_fromDate').getValue();
    if (dateVal.length == 8) {
        if (dateVal.substring(0, 4) < 1999) {
            await $c.win.alert("조회는 1999년 1월 1일 이후부터 가능합니다.");
            $c.util.getComponent('cal_fromDate').setValue("1999-01-01");
            return false;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        fnAKCKwdSearchCorpNameAll();
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        await scwin.fnOrder("1", "D");
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", '');
    if (items.length == 1) {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", items[0].isurcd);
        await scwin.fnSearchCorpCode();
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode();
    }
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isurCd = ($c.util.getComponent("dma_fnDownloadReq").get("isurCd") || '');
    if (isurCd === "") {
        await $c.win.alert("조회한 회사명이 존재하지 않습니다. \n정확한 회사명을 입력해 주세요. \n회사명이 정확하지 않으시면 회사명 검색을 이용해주세요.");
        return;
    } else {
        await scwin.fnOrder("1", "D");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm ipt_comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + ipt_comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (ipt_repIsuSrtCd === "") {
        ipt_repIsuSrtCd = isurCd;
    }
    $c.util.getComponent('AKCKwd').setValue(ipt_comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDetailView
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurcd bzProcsNo
 * @returns
 * @hidden N
*/
scwin.fnDetailView = async function (isurcd, bzProcsNo) {
    /* sdd-asis-lifecycle:begin fnDetailView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let frm = (document.popNewForm || { elements: [] });
    const html = "<form name='popNewForm' ipt_method='post'><input type='hidden' name='isurCd' value='" + isurcd + "'/><input type='hidden' name='bzProcsNo' value='" + bzProcsNo + "'></form>";
    if (frm === "undefined" || frm == null) {
        $("section").first().append(html);
        frm = (document.popNewForm || { elements: [] });
    } else {
        $c.util.getComponent('dma_fnDownloadReq').set('isurCd', isurcd);
        frm.bzProcsNo.value = bzProcsNo;
    }
    const pop_title = "popup";
    const wUrl = "/listinvstg/listcomdetail.do?method=searchListComDetailMain";
    $c.win.openPopup("", String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); let k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof pop_title !== 'undefined' ? pop_title : '') ? Object.assign({ id: "popup", scrollbars: true, resizable: false, width: "970", height: "770", type: "pageFramePopup" }, { id: (typeof pop_title !== 'undefined' ? pop_title : '') }) : { id: "popup", scrollbars: true, resizable: false, width: "970", height: "770", type: "pageFramePopup" }), {});
    frm.target = pop_title;
    frm.action = wUrl;
    await moveUrl(wUrl, {});
    /* sdd-asis-lifecycle:end */
};
